    cols = len(grid[0])

    colors = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                v = grid[r][c]
                if v not in colors:
                    colors[v] = []
                colors[v].append((r, c))

    kernel_color = None
    kernel_center = None
    for color, cells in colors.items():
        if len(cells) == 5:
            rs = [c[0] for c in cells]
            cs = [c[1] for c in cells]
            cr, cc = (min(rs)+max(rs))//2, (min(cs)+max(cs))//2
            expected = {(cr-1,cc-1),(cr-1,cc+1),(cr,cc),(cr+1,cc-1),(cr+1,cc+1)}
            if set(cells) == expected:
                kernel_color = color
                kernel_center = (cr, cc)

    other_color = None
    for color in colors:
        if color != kernel_color:
            other_color = color

    result = [row[:] for row in grid]
    cr, cc = kernel_center

    for r, c in colors[other_color]:
        dr, dc = r - cr, c - cc
        for sr, sc in [(-1, 1), (1, -1), (-1, -1)]:
            nr, nc = cr + dr * sr, cc + dc * sc
            if 0 <= nr < rows and 0 <= nc < cols:
                result[nr][nc] = other_color

